#!/usr/bin/env bash
# Optimal-epoch study (2026-06-10 task) — PSEUDO-LABEL variant, FULL-CHAIN sweep.
#
#   Usage: bash tools_incremental/run_pseudo_v4_epochs.sh <3stage|6stage> <EPOCHS> [GPU_ID]
#
# Like run_pseudo_v4.sh but the WHOLE chain runs at epoch budget E. Crucially the
# epoch count is global: stage1 seeds from the E-epoch NAIVE stage1, and each
# stage t's pseudo-labels are generated by the E-epoch stage_{t-1} teacher (so a
# 4-epoch stage3 is taught by a 4-epoch stage2 teacher). E=12 already exists as
# work_dirs/incremental_v4_pseudo; only sweep {2,4,6,8}.
set -euo pipefail

ORDERING="${1:?usage: run_pseudo_v4_epochs.sh <3stage|6stage> <EPOCHS> [GPU]}"
E="${2:?epoch budget}"
GPU_ID="${3:-0}"
REPO="$(cd "$(dirname "$0")/.." && pwd)"
PY="$REPO/venv/bin/python"
CFG_DIR="$REPO/configs/tr3d_incremental_v4/$ORDERING"
DATA_DIR="$REPO/data/sunrgbd_incremental/v4_3dbox/$ORDERING"
CARVE="$DATA_DIR/carve_report_v4.json"
OUT_ROOT="$REPO/work_dirs/incremental_v4_pseudo_ep${E}/$ORDERING"
NAIVE_EP_S1="$REPO/work_dirs/incremental_v4_naive_ep${E}/$ORDERING/stage1"
SCORE_THR="${SCORE_THR:-0.5}"
[ -d "$CFG_DIR" ] || { echo "no configs at $CFG_DIR"; exit 1; }

# rescaled lr milestones (same rule as the naive epoch sweep)
M1=$(( 2*E/3 )); M2=$(( 11*E/12 ))
[ "$M1" -lt 1 ] && M1=1
[ "$M2" -ge "$E" ] && M2=$(( E-1 ))
[ "$M1" -ge "$E" ] && M1=$(( E-1 ))
if [ "$M1" -ge "$M2" ]; then STEP="[$M1]"; else STEP="[$M1, $M2]"; fi
[ "$M1" -lt 1 ] && STEP="[1]"

export CUDA_VISIBLE_DEVICES="$GPU_ID"
mapfile -t CFGS < <(ls "$CFG_DIR"/stage*.py | sort -V)
echo "=================================================================="
echo "[pseudo-ep$E/$ORDERING] E=$E | lr step=$STEP | GPU=$GPU_ID | score_thr=$SCORE_THR"
echo "[pseudo-ep$E/$ORDERING] out=$OUT_ROOT | started: $(date -Is)"
echo "=================================================================="

# Seed stage1 from the E-epoch naive stage1 (identical: no old classes at stage1).
PSEUDO_S1="$OUT_ROOT/stage1"
if [ -e "$NAIVE_EP_S1/latest.pth" ] && [ ! -e "$PSEUDO_S1/latest.pth" ]; then
  mkdir -p "$PSEUDO_S1"
  cp "$NAIVE_EP_S1/latest.pth" "$PSEUDO_S1/latest.pth"
  [ -e "$NAIVE_EP_S1/eval.log" ] && cp "$NAIVE_EP_S1/eval.log" "$PSEUDO_S1/eval.log"
  echo "[seed] reused E=$E naive stage1 -> $PSEUDO_S1"
else
  echo "[warn] no E=$E naive stage1 at $NAIVE_EP_S1 (run naive sweep first); will train stage1 fresh"
fi

PREV_CKPT=""; PREV_CFG=""
for CFG in "${CFGS[@]}"; do
  STAGE="$(basename "$CFG" .py)"
  WORK_DIR="$OUT_ROOT/$STAGE"
  mkdir -p "$WORK_DIR"
  echo ""
  echo "######## [pseudo-ep$E/$ORDERING/$STAGE] $(date -Is) ########"

  # epoch-overridden config (distinct 'pep' prefix so it never clashes with the naive sweep's ep* cfgs)
  ECFG="$CFG_DIR/pep${E}_$STAGE.py"
  cp "$CFG" "$ECFG"
  cat >> "$ECFG" <<EOF

# ---- pseudo epoch-sweep overrides (auto-appended) ----
runner = dict(type='EpochBasedRunner', max_epochs=$E)
lr_config = dict(policy='step', warmup=None, step=$STEP)
work_dir = '$WORK_DIR'
EOF

  if [ -e "$WORK_DIR/latest.pth" ] && [ -e "$WORK_DIR/eval.log" ]; then
    echo "[skip] $STAGE already complete"
    PREV_CKPT="$WORK_DIR/latest.pth"; PREV_CFG="$ECFG"; continue
  fi

  TRAIN_ARGS=("$ECFG" --work-dir "$WORK_DIR" --seed 0 --deterministic)
  if [ "$STAGE" != "stage1" ]; then
    INIT="$WORK_DIR/init_expanded.pth"
    echo "[expand] $PREV_CKPT -> $INIT"
    "$PY" "$REPO/tools_incremental/expand_head.py" --prev "$PREV_CKPT" --cfg "$ECFG" --out "$INIT"

    TRAIN_PKL="$DATA_DIR/sunrgbd_infos_train_${STAGE}.pkl"
    PSEUDO_PKL="$WORK_DIR/sunrgbd_infos_train_${STAGE}_pseudo.pkl"
    echo "[pseudo] E=$E teacher $PREV_CKPT (cfg=$PREV_CFG) -> $PSEUDO_PKL (thr=$SCORE_THR)"
    "$PY" "$REPO/tools_incremental/make_pseudo_labels.py" \
        --prev-cfg "$PREV_CFG" --prev-ckpt "$PREV_CKPT" \
        --train-pkl "$TRAIN_PKL" --carve-report "$CARVE" \
        --out-pkl "$PSEUDO_PKL" --raw-dets "$WORK_DIR/raw_dets.pkl" \
        --score-thr "$SCORE_THR" --gpu-id 0

    TRAIN_ARGS+=(--cfg-options "load_from=$INIT" "data.train.dataset.ann_file=$PSEUDO_PKL")
  fi

  echo "[train E=$E] $PY tools/train.py ${TRAIN_ARGS[*]}"
  "$PY" "$REPO/tools/train.py" "${TRAIN_ARGS[@]}"
  PREV_CKPT="$WORK_DIR/latest.pth"; PREV_CFG="$ECFG"
  [ -e "$PREV_CKPT" ] || { echo "ERROR: no checkpoint at $PREV_CKPT"; exit 2; }

  echo "[eval] cumulative val -> $WORK_DIR/eval.log"
  "$PY" "$REPO/tools/test.py" "$ECFG" "$PREV_CKPT" \
      --out "$WORK_DIR/results.pkl" --eval mAP 2>&1 | tee "$WORK_DIR/eval.log"
done

echo ""
echo "[pseudo-ep$E/$ORDERING] COMPLETE: $(date -Is)"
